function getKillBalls(ctx) {
  var offsets=ctx.params.offsets, target=ctx.params.target, blue=ctx.params.blue;
  var h=ctx.history(offsets.length); if(h.length!==offsets.length) return [];
  var max=blue?16:33, killed={};
  for(var anchor=1;anchor<=max;anchor++) {
    for(var sign=-1;sign<=1;sign+=2) {
      var next=anchor+sign*target; if(next<1||next>max) continue;
      var matches=true;
      for(var row=0;row<offsets.length;row++) {
        var b=anchor+sign*offsets[row];
        if(b<1||b>max || (blue?h[row].blueBall!==b:h[row].redBalls.indexOf(b)<0)) { matches=false; break; }
      }
      if(matches) killed[next]=true;
    }
  }
  return Object.keys(killed).map(function(b){return parseInt(b,10);}).sort(function(a,b){return a-b;});
}

